window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-649dd8eb3aea4192"]={"versions": [{"id": "FIG-649dd8eb3aea4192", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Erweiterung) im Kontext des AUTOSAR Template Modeling Guide. Das Diagramm definiert das Profil <code>AUTOSARTemplateProfile</code> und zeigt die Spezialisierung und Erweiterung von Metaklassen des UML-Metamodells (<code>Kernel</code>) durch spezifische AUTOSAR-Template-Stereotypen (<code>atp*</code> sowie Literal-Erweiterungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Profil <code>AUTOSARTemplateProfile</code> umfasst folgende Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklassen-Erweiterungen (<code>«extends»</code>, teils mit <code>{required}</code>):\n<ul class=\"fig-list\"><li><code>Kernel::Class</code> wird erweitert durch <code>atpClass</code>.\n</li><li><code>Kernel::Property</code> wird erweitert durch <code>atpAttribute</code>.\n</li><li><code>Kernel::Dependency</code> wird erweitert durch <code>atpDependency</code>.\n</li><li><code>Kernel::Package</code> wird erweitert durch <code>atpPackage</code>.\n</li><li>Diverse Kernel-Metaklassen für Literale (<code>Kernel::String</code>, <code>Kernel::Integer</code>, <code>Kernel::UnlimitedNatural</code>, <code>Kernel::LiteralBoolean</code>, <code>Kernel::LiteralInteger</code>, <code>Kernel::LiteralString</code>) werden importiert bzw. durch Literalspezifikationen erweitert.\n</li></ul>\n</li><li>Spezialisierungen (<code>«generalization»</code>):\n<ul class=\"fig-list\"><li>Von <code>atpClass</code> erben spezialisierte Stereotypen (z. B. für Template-Strukturen).\n</li><li>Von <code>atpAttribute</code> erben attributspezifische Stereotypen.\n</li><li>Von <code>atpDependency</code> erben Abhängigkeits-Stereotypen.\n</li></ul>\n</li><li>Literal-Spezifikationen:\n<ul class=\"fig-list\"><li>Stereotyp <code>LiteralFloat</code> mit Relation <code>isOfType</code>.\n</li><li>Weitere Literal-Stereotypen für Basistypen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches UML-Metamodell-/Profildiagramm ohne dynamische Laufzeit- oder Sequenzabläufe. Es definiert die statischen syntaktischen und semantischen Konstrukte sowie Stereotyp-Hierarchien zur Erstellung AUTOSAR-konformer Vorlagenmodelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Templates und Metamodell-Werkzeuge. Modellelemente in AUTOSAR-Templates müssen die definierten Profilstereotypen (<code>atp*</code>) gemäß den dokumentierten Erweiterungsregeln und Generalisierungsbeziehungen anwenden. Erweiterungen mit <code>{required}</code> erzwingen die Ausprägung der entsprechenden Stereotypen an den jeweiligen UML-Kernel-Metaklassen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-58da839022be0ce7", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Erweiterung) im Kontext des AUTOSAR Template Modeling Guide. Das Diagramm definiert das Profil <code>AUTOSARTemplateProfile</code> und zeigt die Spezialisierung und Erweiterung von Metaklassen des UML-Metamodells (<code>Kernel</code>) durch spezifische AUTOSAR-Template-Stereotypen (<code>atp*</code> sowie Literal-Erweiterungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Profil <code>AUTOSARTemplateProfile</code> umfasst folgende Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklassen-Erweiterungen (<code>«extends»</code>, teils mit <code>{required}</code>):\n<ul class=\"fig-list\"><li><code>Kernel::Class</code> wird erweitert durch <code>atpClass</code>.\n</li><li><code>Kernel::Property</code> wird erweitert durch <code>atpAttribute</code>.\n</li><li><code>Kernel::Dependency</code> wird erweitert durch <code>atpDependency</code>.\n</li><li><code>Kernel::Package</code> wird erweitert durch <code>atpPackage</code>.\n</li><li>Diverse Kernel-Metaklassen für Literale (<code>Kernel::String</code>, <code>Kernel::Integer</code>, <code>Kernel::UnlimitedNatural</code>, <code>Kernel::LiteralBoolean</code>, <code>Kernel::LiteralInteger</code>, <code>Kernel::LiteralString</code>) werden importiert bzw. durch Literalspezifikationen erweitert.\n</li></ul>\n</li><li>Spezialisierungen (<code>«generalization»</code>):\n<ul class=\"fig-list\"><li>Von <code>atpClass</code> erben spezialisierte Stereotypen (z. B. für Template-Strukturen).\n</li><li>Von <code>atpAttribute</code> erben attributspezifische Stereotypen.\n</li><li>Von <code>atpDependency</code> erben Abhängigkeits-Stereotypen.\n</li></ul>\n</li><li>Literal-Spezifikationen:\n<ul class=\"fig-list\"><li>Stereotyp <code>LiteralFloat</code> mit Relation <code>isOfType</code>.\n</li><li>Weitere Literal-Stereotypen für Basistypen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches UML-Metamodell-/Profildiagramm ohne dynamische Laufzeit- oder Sequenzabläufe. Es definiert die statischen syntaktischen und semantischen Konstrukte sowie Stereotyp-Hierarchien zur Erstellung AUTOSAR-konformer Vorlagenmodelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Templates und Metamodell-Werkzeuge. Modellelemente in AUTOSAR-Templates müssen die definierten Profilstereotypen (<code>atp*</code>) gemäß den dokumentierten Erweiterungsregeln und Generalisierungsbeziehungen anwenden. Erweiterungen mit <code>{required}</code> erzwingen die Ausprägung der entsprechenden Stereotypen an den jeweiligen UML-Kernel-Metaklassen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-448964c314fd1c38", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Profildiagramm (Metamodell-Erweiterung) im Kontext des AUTOSAR Template Modeling Guide. Das Diagramm definiert das Profil <code>AUTOSARTemplateProfile</code> und zeigt die Spezialisierung und Erweiterung von Metaklassen des UML-Metamodells (<code>Kernel</code>) durch spezifische AUTOSAR-Template-Stereotypen (<code>atp*</code> sowie Literal-Erweiterungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Profil <code>AUTOSARTemplateProfile</code> umfasst folgende Stereotypen und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Metaklassen-Erweiterungen (<code>«extends»</code>, teils mit <code>{required}</code>):\n<ul class=\"fig-list\"><li><code>Kernel::Class</code> wird erweitert durch <code>atpClass</code>.\n</li><li><code>Kernel::Property</code> wird erweitert durch <code>atpAttribute</code>.\n</li><li><code>Kernel::Dependency</code> wird erweitert durch <code>atpDependency</code>.\n</li><li><code>Kernel::Package</code> wird erweitert durch <code>atpPackage</code>.\n</li><li>Kernel-Metaklassen für Literale (<code>Kernel::String</code>, <code>Kernel::Integer</code>, <code>Kernel::UnlimitedNatural</code>, <code>Kernel::LiteralBoolean</code>, <code>Kernel::LiteralInteger</code>, <code>Kernel::LiteralString</code>) werden importiert bzw. durch entsprechende Literalspezifikationen erweitert.\n</li></ul>\n</li><li>Spezialisierungen (<code>«generalization»</code>):\n<ul class=\"fig-list\"><li>Von <code>atpClass</code> erben spezialisierte Stereotypen für Template-Klassen.\n</li><li>Von <code>atpAttribute</code> erben attributspezifische Stereotypen.\n</li><li>Von <code>atpDependency</code> erben spezifische Abhängigkeits-Stereotypen.\n</li></ul>\n</li><li>Literal-Spezifikationen:\n<ul class=\"fig-list\"><li>Definitionen für Boolean-, Integer-, String- und UnlimitedNatural-Literale ohne Gleitkomma-Literalstereotyp (<code>LiteralFloat</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches UML-Metamodell-/Profildiagramm ohne dynamische Laufzeit- oder Sequenzabläufe. Es definiert die statischen syntaktischen und semantischen Konstrukte sowie Stereotyp-Hierarchien zur Erstellung AUTOSAR-konformer Vorlagenmodelle.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Autoren von AUTOSAR-Templates und Metamodell-Werkzeuge. Modellelemente in AUTOSAR-Templates müssen die definierten Profilstereotypen (<code>atp*</code>) gemäß den dokumentierten Erweiterungsregeln und Generalisierungsbeziehungen anwenden. Erweiterungen mit <code>{required}</code> erzwingen die Ausprägung der entsprechenden Stereotypen an den jeweiligen UML-Kernel-Metaklassen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-649dd8eb3aea4192", "to": "FIG-58da839022be0ce7", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-58da839022be0ce7", "to": "FIG-448964c314fd1c38", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Der Stereotyp <code>LiteralFloat</code> (Spezialisierung von <code>LiteralSpecification</code>, erweitert <code>Kernel::LiteralReal</code> bzw. Metaklassen) sowie dessen Abhängigkeit/Assoziation <code>isOfType</code> entfallen vollständig aus dem Profil.\n</li></ul>"}]};
